1618: /// Reject a UUID selection whose advertised fragments still depend on an unselected segment.
1619: fn reject_incomplete_segment_contributors(
1620:     index_name: &str,
1621:     indices: &[IndexMetadata],
1622:     selected_uuids: &HashSet<Uuid>,
1623:     selected_coverage: &RoaringBitmap,
1624: ) -> Result<()> {
1625:     let mut missing = Vec::new();
1626:     let mut shared_fragments = RoaringBitmap::new();
1627:     for segment in indices {
1628:         if segment.name != index_name || selected_uuids.contains(&segment.uuid) {
1629:             continue;
1630:         }
1631:         let Some(coverage) = segment.fragment_bitmap.as_ref() else {
1632:             continue;
1633:         };
1634:         let overlap = coverage & selected_coverage;
1635:         if overlap.is_empty() {
1636:             continue;
1637:         }
1638:         shared_fragments |= overlap;
1639:         missing.push(segment.uuid);
1640:     }
1641:     if missing.is_empty() {
1642:         return Ok(());
1643:     }
1644:     missing.sort_unstable();
1645:     Err(Error::invalid_input(format!(
1646:         "Scalar index '{index_name}' selection omits contributing segments {missing:?} for fragments {:?}. Select every segment that covers those fragments",
1647:         shared_fragments.iter().collect::<Vec<_>>()
1648:     )))
1649: }

