3848:     ///
3849:     /// `next` runs under the `state` write lock on the current schema, so a
3850:     /// caller changing only the schema or only the indexes keeps the other.
3851:     /// `Ok(None)` when nothing would change.
3852:     async fn replace_writer_schema(
3853:         &self,
3854:         op: &'static str,
3855:         next: impl FnOnce(&WriterSchema) -> Result<WriterSchema>,
3856:     ) -> Result<Option<SealFence>> {
3857:         let WriterMode::MemTable {
3858:             state,
3859:             writer_state,
3860:             ..
3861:         } = &self.mode
3862:         else {
3863:             return Err(Error::invalid_input(format!(
3864:                 "{op} is not available in WAL-only mode (no MemTable)"
3865:             )));
3866:         };
3867:         self.check_fenced().await?;
3868:         self.wal_flusher.check_poisoned()?;
3869: 
3870:         let mut state = state.write().await;
3871:         let current = Arc::clone(&state.schema);
3872:         let next = Arc::new(next(&current)?);
3873:         if next.is_equivalent(&current) {
3874:             return Ok(None);
3875:         }
3876:         if next.pk_field_ids != current.pk_field_ids {
3877:             return Err(Error::invalid_input(format!(
3878:                 "{op} cannot change the primary key: the writer holds primary key field ids \
3879:                  {:?} ({:?}) and the new schema declares {:?} ({:?})",
3880:                 current.pk_field_ids, current.pk_columns, next.pk_field_ids, next.pk_columns,
3881:             )));
3882:         }
3883: 
3884:         let sealed_generation = if state.memtable.batch_count() == 0 {
3885:             // Nothing written yet: replace it in place under the same generation.
3886:             let generation = state.memtable.generation();
3887:             let global_offset = state.memtable.batch_store().global_end();
3888:             state.memtable = next.new_memtable(
3889:                 generation,
3890:                 global_offset,
3891:                 None,
3892:                 writer_state.epoch,
3893:                 writer_state.max_memtable_rows,
3894:                 writer_state.max_memtable_batches,
3895:                 self.wal_flusher.cursors(),
3896:             )?;
3897:             state.schema = next;
3898:             publish_memory(&writer_state.memory, &state);
3899:             None
3900:         } else {
3901:             let sealed = state.memtable.generation();
3902:             writer_state.rotate_memtable(&mut state, next)?;
3903:             Some(sealed)
3904:         };
3905:         info!(
3906:             "{op} moved shard {} (epoch {}) onto a new schema: active generation {}, sealed {:?}",
3907:             self.config.shard_id,
3908:             self.epoch,
3909:             state.memtable.generation(),
3910:             sealed_generation,
3911:         );
