410: fn stored_names(
411:     stored_schema: &Schema,
412:     table_schema: &Schema,
413: ) -> (HashMap<String, String>, HashMap<String, String>) {
414:     let table = field_paths(table_schema);
415:     // Keyed by id and path style: a list element has a projection path and a
416:     // full-text path, and mixing them would give the index a path it lacks.
417:     let by_id: HashMap<(i32, bool), &String> = table
418:         .iter()
419:         .filter_map(|(id, elided, path)| id.map(|id| ((id, *elided), path)))
420:         .collect();
421:     // Without ids, match by name: a path maps to itself if the table has it.
422:     if by_id.is_empty() {
423:         let known: std::collections::HashSet<&String> =
424:             table.iter().map(|(_, _, path)| path).collect();
425:         let mut physical = HashMap::new();
426:         let mut fts = HashMap::new();
427:         for (_, elided, path) in field_paths(stored_schema) {
428:             if !known.contains(&path) {
429:                 continue;
430:             }
431:             let into = if elided { &mut fts } else { &mut physical };
432:             into.insert(path.clone(), path);
433:         }
434:         return (physical, fts);
435:     }
436:     let mut physical = HashMap::new();
437:     let mut fts = HashMap::new();
438:     for (id, elided, stored_path) in field_paths(stored_schema) {
439:         let Some(id) = id else { continue };
440:         let Some(table_path) = by_id.get(&(id, elided)) else {
441:             continue;
442:         };
443:         let into = if elided { &mut fts } else { &mut physical };
444:         into.insert(stored_path, (*table_path).clone());
445:     }
446:     (physical, fts)
447: }
