584:     /// Given a batch of `num_rows`, walk through the deletion vector, and figure out where blanks
585:     /// should be inserted.
586:     ///
587:     /// For example, if self.current_row_id is 10 and the deletion vector is [11, 12, 19, 25] and
588:     /// num_rows is 7 then this function will at least return [1, 2] and the batch will at least
589:     /// span row ids 10..18.
590:     ///
591:     /// Then, in the example we need to choose whether the returned batch should include
592:     /// row 19 (and have 10 rows) or not (and have 9 rows).  This is only a concern in v1 files
593:     /// where we want to match the original row group size (which is the batch size).  If the
594:     /// batch size is 9 then we do not include 19 and return as above.
595:     ///
596:     /// If the maximum output size is 10 then we include 19 and return [1, 2, 9].
597:     ///
598:     /// In v2 files we stop at the configured output batch size. Any remaining deleted rows
599:     /// are handled by later input batches or emitted as bounded blank-only batches.
600:     fn deleted_batch_offsets_in_range(&mut self, mut num_rows: u32) -> Result<Vec<u32>> {
759:     /// Materialize one bounded chunk of blanks deferred by empty input batches.
760:     ///
761:     /// `source` supplies values for layouts that have no cheaper synthetic blank.
762:     /// `plans` must have been produced by [`blank_plans`] for `source`.
763:     fn take_pending_blanks_with_plans(
764:         &mut self,
765:         source: &RecordBatch,
766:         plans: &[BlankPlan],
767:     ) -> Result<Option<RecordBatch>> {
768:         if self.pending_blank_rows == 0 {
769:             return Ok(None);
770:         }
771:         debug_assert_eq!(source.num_rows(), 1);
772: 
773:         let chunk_size = self.pending_blank_rows.min(self.max_output_rows.get());
774:         let batch_offsets = (0..chunk_size).collect::<Vec<_>>();
775:         let with_source = add_blanks_with_plans(source.clone(), &batch_offsets, plans)?;
776:         // Offsets `0..n` put the blanks first and append the whole source, so exactly
777:         // one row -- the source itself -- has to come back off the end. Check the
778:         // coupling rather than only documenting it in `add_blanks`.
779:         debug_assert_eq!(with_source.num_rows(), chunk_size as usize + 1);
780:         self.pending_blank_rows -= chunk_size;
781:         Ok(Some(with_source.slice(0, chunk_size as usize)))
782:     }
783: }
