529: /// stops the walk as soon as the answer is settled.
530: pub(crate) async fn count_trainable_vectors(
531:     dataset: &Dataset,
532:     column: &str,
533:     total_rows: usize,
534:     enough: usize,
535: ) -> Result<usize> {
536:     let is_multivector = is_multivector(dataset, column)?;
537:     if !is_multivector
538:         && dataset
539:             .schema()
540:             .field(column)
541:             .is_some_and(|field| !field.nullable)
542:     {
543:         return Ok(total_rows);
544:     }
545:     if enough == 0 {
546:         return Ok(0);
547:     }
548: 
549:     let mut scanner = dataset.scan();
550:     scanner.project(&[column])?;
551:     // These callers need a threshold, not a full count. Bound prefetch so a
552:     // small training floor does not schedule reads from the rest of the table.
553:     // Keep batches large enough to also scan sparse or all-null inputs efficiently.
554:     scanner
555:         .batch_size(1024)
556:         .batch_readahead(1)
557:         .fragment_readahead(1);
558:     let mut batches = scanner.try_into_stream().await?;
559:     let mut vectors = 0_usize;
560:     while let Some(batch) = batches.try_next().await? {
561:         let array = utils::get_column_from_batch(&batch, column)?;
562:         if is_multivector {
563:             let lists = array.as_list::<i32>();
564:             for row in 0..lists.len() {
565:                 if lists.is_null(row) {
566:                     continue;
567:                 }
568:                 // Null vectors inside a non-null list cannot be trained on.
569:                 let row_vectors = lists.value(row);
570:                 vectors = vectors.saturating_add(row_vectors.len() - row_vectors.null_count());
571:             }
572:         } else {
573:             vectors = vectors.saturating_add(array.len() - array.null_count());
574:         }
575:         if vectors >= enough {
576:             return Ok(vectors);
577:         }
578:     }

